440→            if (flushTimerRef.current) {
441→              clearTimeout(flushTimerRef.current);
442→              flushTimerRef.current = null;
443→            }
444→            flushText();
445→            if (currentTextRef.current.trim()) {
446→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
447→              currentTextRef.current = '';
448→            }
449→            setMessages((prev) =>
450→              prev.map((m) =>
451→                m.id === assistantId
452→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
453→                  : m
454→              )
455→            );
456→            setIsStreaming(false);
457→            abortRef.current = null;
458→          },
459→          onError: (error) => {
460→            if (flushTimerRef.current) {
461→              clearTimeout(flushTimerRef.current);
462→              flushTimerRef.current = null;
463→            }
464→            flushText();
465→            setMessages((prev) =>
466→              prev.map((m) =>
467→                m.id === assistantId
468→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
469→                  : m
470→              )
471→            );
472→            setIsStreaming(false);
473→            abortRef.current = null;
474→          },
475→          onUserQuestion: (data) => {
476→            if (flushTimerRef.current) {
477→              clearTimeout(flushTimerRef.current);
478→              flushTimerRef.current = null;
479→            }
480→            flushText();
481→            if (currentTextRef.current.trim()) {
482→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
483→              currentTextRef.current = '';
484→            }
485→            segmentsRef.current.push({
486→              type: 'user_question',
487→              questionData: data,
488→            });
489→            setMessages((prev) =>
490→              prev.map((m) =>
491→                m.id === assistantId
492→                  ? { ...m, segments: [...segmentsRef.current] }
493→                  : m
494→              )
495→            );
496→          },
497→        },
498→        controller.signal,
499→        userSessionId,
500→      );
501→    },
502→    [isStreaming, messages, flushText, refreshTables, userSessionId]
503→  );
504→
505→  const deleteMessage = useCallback(
506→    (messageIndex: number) => {
507→      if (isStreaming) return;
508→
509→      // Store remaining messages as history for Langfuse context on next send
510→      setMessages((prev) => {
511→        const remaining = prev.slice(0, messageIndex);
512→        pendingHistoryRef.current = remaining
513→          .filter((m) => m.role === 'user' || m.role === 'assistant')
514→          .map((m) => ({ role: m.role, content: m.content }));
515→        return remaining;
516→      });
517→
518→      // Clear session so next message starts fresh
519→      sessionIdRef.current = null;
520→    },
521→    [isStreaming]
522→  );
523→
524→  const respondToQuestion = useCallback(
525→    async (questionId: string, answers: string[], freeText?: string) => {
526→      // Update the segment to show the user's answer
527→      const segIdx = segmentsRef.current.findIndex(
528→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
529→      );
530→      if (segIdx !== -1) {
531→        segmentsRef.current[segIdx] = {
532→          ...segmentsRef.current[segIdx],
533→          userAnswer: answers,
534→          userFreeText: freeText,
535→        };
536→        setMessages((prev) =>
537→          prev.map((m) =>
538→            m.id === assistantIdRef.current
539→              ? { ...m, segments: [...segmentsRef.current] }
540→              : m
541→          )
542→        );
543→      }
544→
545→      // POST to backend
546→      try {
547→        await fetch('/api/chat/respond', {
548→          method: 'POST',
549→          headers: {
550→            'Content-Type': 'application/json',
551→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
552→          },
553→          body: JSON.stringify({
554→            question_id: questionId,
555→            answers,
556→            free_text: freeText || null,
557→          }),
558→        });
559→      } catch (e) {
560→        console.error('Failed to respond to question:', e);
561→      }
562→    },
563→    [userSessionId]
564→  );
565→
566→  const clearMessages = useCallback(() => {
567→    if (abortRef.current) {
568→      abortRef.current.abort();
569→    }
570→    setMessages([]);
571→    setIsStreaming(false);
572→    sessionIdRef.current = null;
573→    pendingHistoryRef.current = null;
574→  }, []);
575→
576→  return (
577→    <AgentContext.Provider
578→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
579→    >
580→      {children}
581→    </AgentContext.Provider>
582→  );
583→}
